// The one place the family UI talks to the server. With USE_FIXTURES it serves
// fixtures/demo/*.json (generated by `npm run fixtures`) in the same contract shapes.
import { USE_FIXTURES } from './config';
import type { Timeline } from './types';
import drift from '../../fixtures/demo/timeline.json';
import stable from '../../fixtures/demo/timeline-stable.json';
import unconfirmed from '../../fixtures/demo/timeline-unconfirmed.json';
import processing from '../../fixtures/demo/timeline-processing.json';
import afterCall from '../../fixtures/demo/timeline-after-call.json';
import elderFixture from '../../fixtures/demo/elder.json';

export const FIXTURE_VARIANTS = {
  drift: drift as Timeline,
  stable: stable as Timeline,
  unconfirmed: unconfirmed as Timeline,
  processing: processing as Timeline,
  'after-call': afterCall as Timeline,
} as const;
export type FixtureVariant = keyof typeof FIXTURE_VARIANTS;

export const isFixtureVariant = (v: unknown): v is FixtureVariant =>
  typeof v === 'string' && v in FIXTURE_VARIANTS;

export interface ElderSummary { id: string; displayName: string; preferredName: string }

// GET /api/elders/:id — contract §5 lists the parts but not field names; this is D's assumption (see HANDOFF).
export interface ElderProfile extends ElderSummary {
  language: Timeline['elder']['language'];
  timezone: string;
  about: string;
  primaryContactName: string;
  members: { name: string; relation: string }[];
  photos: { id: string; caption: string; people: string; imageUrl: string }[];
  questions: { id: string; text: string; askedBy: string; status: 'pending' | 'asked' | 'answered' }[];
  consent: Timeline['consent'];
}

export async function getElder(elderId: string, variant: FixtureVariant = 'drift'): Promise<ElderProfile> {
  if (USE_FIXTURES) {
    const elder = structuredClone(elderFixture as ElderProfile);
    // After the live call, Sam's question has been asked and answered (the API does this for real).
    if (variant === 'after-call') {
      elder.questions = elder.questions.map((q) => (q.id === 'q-first-car' ? { ...q, status: 'answered' } : q));
    }
    return elder;
  }
  return getJson(`/api/elders/${encodeURIComponent(elderId)}`);
}

async function getJson<T>(path: string): Promise<T> {
  const res = await fetch(path, { cache: 'no-store' });
  if (!res.ok) throw new Error(`${path} → ${res.status}`);
  return res.json() as Promise<T>;
}

export async function getElders(): Promise<ElderSummary[]> {
  if (USE_FIXTURES) {
    const { id, displayName, preferredName } = drift.elder;
    return [{ id, displayName, preferredName }];
  }
  return getJson('/api/elders');
}

export async function getTimeline(elderId: string, variant: FixtureVariant = 'drift'): Promise<Timeline> {
  if (USE_FIXTURES) return structuredClone(FIXTURE_VARIANTS[variant]);
  return getJson(`/api/elders/${encodeURIComponent(elderId)}/timeline`);
}

// Thrown in sample-data mode so the panel can keep the change on screen and say it isn't saved.
export class PreviewOnly extends Error {}

async function send<T>(path: string, init: RequestInit): Promise<T> {
  if (USE_FIXTURES) throw new PreviewOnly('Sample data: not saved');
  const res = await fetch(path, init);
  if (!res.ok) {
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new Error(body?.error ?? `${path} → ${res.status}`);
  }
  return (res.status === 204 ? undefined : await res.json()) as T;
}

type Question = ElderProfile['questions'][number];
type Photo = ElderProfile['photos'][number];

export const addQuestion = (elderId: string, text: string, askedBy: string) =>
  send<Question>(`/api/elders/${encodeURIComponent(elderId)}/questions`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text, askedBy }),
  });

export const removeQuestion = (questionId: string) =>
  send<void>(`/api/questions/${encodeURIComponent(questionId)}`, { method: 'DELETE' });

export function addPhoto(elderId: string, file: File, caption: string, people: string) {
  const form = new FormData();
  form.set('file', file);
  form.set('caption', caption);
  if (people.trim()) form.set('people', people);
  return send<Photo>(`/api/elders/${encodeURIComponent(elderId)}/photos`, { method: 'POST', body: form });
}

export const removePhoto = (photoId: string) =>
  send<void>(`/api/photos/${encodeURIComponent(photoId)}`, { method: 'DELETE' });

export async function dismissNudge(nudgeId: string): Promise<void> {
  if (USE_FIXTURES) return;
  const res = await fetch(`/api/nudges/${encodeURIComponent(nudgeId)}/dismiss`, { method: 'POST' });
  if (!res.ok) throw new Error(`dismiss → ${res.status}`);
}
